import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r}from"./chunks/EN.P9aPnFBv.js";import{_ as a,a as i,b as s}from"./chunks/M-S-SY3.DDtr6WYL.js";import{_ as o}from"./chunks/M-S-SY2.BC5ErUru.js";import{_ as n}from"./chunks/DIS.DdpTdGGD.js";import{_ as l,o as p,c,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Sync Follower setup","description":"","frontmatter":{},"headers":[],"relativePath":"use/syncsetup.md","filePath":"use/syncsetup.md"}'),m={name:"use/syncsetup.md"};function h(u,t,g,y,b,f){return p(),c("div",null,[...t[0]||(t[0]=[d('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip sync</p></div><div class="warning custom-block"><p class="custom-block-title">Old xDrip Sync</p><p>In July 2024, Google shut down the deprecated <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">Firebase API</a> xDrip used for xDrip Sync.<br> Update xDrip to a version from <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">July 23rd 2024</a> to use the legacy Sync method.<br> Updating xDrip to at least the latest release is recommended.</p></div><p>xDrip provides a unique real time sync mechanism between Android devices making BG and treatment sharing the easiest possible task.</p><br><p><a href="https://www.youtube.com/watch?v=LcgjfbYcWkE" target="_blank" rel="noreferrer">Here the original reference video</a>.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Warning</p><p><a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">Google Play services</a> are mandatory to use this feature. Make sure they are present, enabled and not subject to battery optimization.</p></div><p>xDrip master phone is the device that is actually getting glucose readings directly from a sensor, a bridge, an app.<br> Having a follower device being xDrip sync master adds little value unless the follower device can&#39;t use the same data source.</p><p>Your master should receive data reliably. Always troubleshoot the master first if you don&#39;t have data on your follower.</p><h2 id="setup-master" tabindex="-1">Setup master <a class="header-anchor" href="#setup-master" aria-label="Permalink to &quot;Setup master&quot;">​</a></h2><p>Make the primary data source phone master (enable checkbox):</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip sync</p><p>    <strong>Be Master for Followers <span class="symbol" style="float:right;"><img src="'+r+'" style="zoom:75%;">  </span></strong></p></div><br><h3 id="copy-the-sync-key" tabindex="-1">Copy the Sync Key <a class="header-anchor" href="#copy-the-sync-key" aria-label="Permalink to &quot;Copy the Sync Key&quot;">​</a></h3><h4 id="option-1-recommended" tabindex="-1">Option 1 (recommended) <a class="header-anchor" href="#option-1-recommended" aria-label="Permalink to &quot;Option 1 (recommended)&quot;">​</a></h4><p>On the master phone display the Sync Key QR code:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"> Show Settings QR codes</p><div style="background-color:gray;color:white;text-align:center;">  XDRIP PLUS SECURITY KEY SETTINGS ONLY </div></div><p>Leave the master phone on this picture for the moment.</p><img src="'+a+'" style="zoom:75%;"><h5 id="option-1-bis-follower-phone-cannot-read-the-qr-code" tabindex="-1">Option 1 bis (follower phone cannot read the QR code) <a class="header-anchor" href="#option-1-bis-follower-phone-cannot-read-the-qr-code" aria-label="Permalink to &quot;Option 1 bis (follower phone cannot read the QR code)&quot;">​</a></h5><p>Take a screenshot of the QR code and send it to the follower phone (MMS, WhatsApp, upload to Google Cloud, ...).</p><h4 id="option-2-complicated" tabindex="-1">Option 2 (complicated) <a class="header-anchor" href="#option-2-complicated" aria-label="Permalink to &quot;Option 2 (complicated)&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip sync</p><p>    <strong>Handset Group Security Sync Key</strong></p></div><img src="'+o+'" style="zoom:75%;"><br><h2 id="setup-follower" tabindex="-1">Setup follower <a class="header-anchor" href="#setup-follower" aria-label="Permalink to &quot;Setup follower&quot;">​</a></h2><p>Make all other phones followers (disable checkbox):</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip sync</p><p>    <strong>Be Master for Followers <span class="symbol" style="float:right;"><img src="'+n+'" style="zoom:75%;">  </span></strong></p></div><br><p>Set the follower data source:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   xDrip Sync Follower</p></div><p>More about the <a href="./../install/xdripfollower.html">xDrip Sync Follower</a> data source.</p><br><div class="warning custom-block"><p class="custom-block-title">Use xDrip Cloud must be set identically on all phones</p><p>Master and followers. Either it is ON for all, or OFF for all.</p></div><div class="admonition xdripitem"><p class="admonition-title">Use xDrip Cloud</p><p> Use the new xDrip cloud servers. Master and followers must all have this setting set the same.</p></div><p>Enabling <a href="./sync.html#use-xdrip-cloud">Use xDrip Cloud</a> on all devices is recommended as the more future-proof method.</p><h3 id="copy-the-sync-key-from-the-master" tabindex="-1">Copy the Sync Key from the master <a class="header-anchor" href="#copy-the-sync-key-from-the-master" aria-label="Permalink to &quot;Copy the Sync Key from the master&quot;">​</a></h3><h4 id="option-1-recommended-1" tabindex="-1">Option 1 (recommended) <a class="header-anchor" href="#option-1-recommended-1" aria-label="Permalink to &quot;Option 1 (recommended)&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Auto configure<br>    Camera</p></div><p>You need to authorize xDrip to access the phone camera.<br> Scan the QR code displayed on your master phone.</p><img src="'+i+'" style="zoom:75%;"><p>You will be asked to confirm you want to import these settings (make sure you import safe settings).</p><div class="admonition xdripitem"><p class="admonition-title">Are you sure?</p><p> Only import settings from sources you trust!<br>  Please confirm to import the following settings:</p><p> setting1<br>  setting2<br>  setting3</p><p>No  <span style="background-color:gray;color:white;text-align:center;"> Yes </span></p></div><h4 id="option-1-bis-follower-phone-cannot-read-the-qr-code-1" tabindex="-1">Option 1 bis (follower phone cannot read the QR code) <a class="header-anchor" href="#option-1-bis-follower-phone-cannot-read-the-qr-code-1" aria-label="Permalink to &quot;Option 1 bis (follower phone cannot read the QR code)&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Auto configure<br>    Image file</p></div><p>Select the image containing the QR code.</p><img src="'+s+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Are you sure?</p><p> Only import settings from sources you trust!<br>  Please confirm to import the following settings:</p><p> setting1<br>  setting2<br>  setting3</p><p>No  <span style="background-color:gray;color:white;text-align:center;"> Yes </span></p></div><h4 id="option-2-complicated-1" tabindex="-1">Option 2 (complicated) <a class="header-anchor" href="#option-2-complicated-1" aria-label="Permalink to &quot;Option 2 (complicated)&quot;">​</a></h4><p>Edit the key field and type <strong>exactly</strong> the same key as the master.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip sync</p><p>    <strong>Handset Group Security Sync Key</strong></p></div><img src="'+o+'" style="zoom:75%;"><br><h2 id="follower-actions" tabindex="-1">Follower actions <a class="header-anchor" href="#follower-actions" aria-label="Permalink to &quot;Follower actions&quot;">​</a></h2><p>By default, followers can send treatments, calibrations, and even sensor start or stop to the master.<br> If you want to prevent this, disable <a href="./sync.html#accept-followers-actions">Accept follower actions</a> on the master.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>To verify the follower is receiving data, check <a href="./../troubleshoot/systemstatus.html#xdrip-sync-follower">System Status</a> on the follower phone.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',59)])])}const D=l(m,[["render",h]]);export{q as __pageData,D as default};
